const translatableAttributes=['placeholder','aria-label','alt','title','content'];
const originalNodes=[];
const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
while(walker.nextNode()){
 const node=walker.currentNode;const value=node.nodeValue;const key=value.trim();
 if(key&&Object.prototype.hasOwnProperty.call(zh,key)) originalNodes.push([node,value,key]);
}
const originalAttributes=[];
for(const el of document.querySelectorAll('*'))for(const attr of translatableAttributes){
 if(!el.hasAttribute(attr))continue;const value=el.getAttribute(attr);
 if(Object.prototype.hasOwnProperty.call(zh,value))originalAttributes.push([el,attr,value]);
}
const titleEnglish=document.title;const description=document.querySelector('meta[name="description"]');
const descriptionEnglish=description?.content||'';
const switchButton=document.createElement('button');
switchButton.type='button';switchButton.className='language-switch';switchButton.setAttribute('aria-label','Switch language');
const header=document.querySelector('.site-header');header?.insertBefore(switchButton,header.querySelector('.menu-button'));
function setLanguage(language,remember=false){
 const chinese=language==='zh';document.documentElement.lang=chinese?'zh-Hans':'en';
 document.documentElement.dataset.language=chinese?'zh':'en';
 for(const [node,value,key] of originalNodes){const replacement=chinese?zh[key]:key;node.nodeValue=value.replace(key,replacement)}
 for(const [el,attr,value] of originalAttributes)el.setAttribute(attr,chinese?zh[value]:value);
 document.title=chinese?(zh[titleEnglish]||titleEnglish):titleEnglish;
 if(description)description.content=chinese?'MIPES 多域训练系统、ARTS 自主机器人靶标及训练配套产品。':descriptionEnglish;
 switchButton.textContent=chinese?'EN':'中文';switchButton.setAttribute('aria-label',chinese?'Switch to English':'切换到简体中文');switchButton.title=chinese?'English':'简体中文';
 if(remember)try{localStorage.setItem('mipes-language',language)}catch{}
 const menu=document.getElementById('menuButton');if(menu)menu.setAttribute('aria-label',chinese?(menu.getAttribute('aria-expanded')==='true'?'关闭菜单':'打开菜单'):(menu.getAttribute('aria-expanded')==='true'?'Close menu':'Open menu'));
 window.dispatchEvent(new CustomEvent('mipes:languagechange',{detail:{language}}));
}
let savedLanguage=null;try{savedLanguage=localStorage.getItem('mipes-language')}catch{}
const systemLanguage=(navigator.languages&&navigator.languages[0])||navigator.language||'en';
const systemChinese=/^zh(?:-|$)/i.test(systemLanguage);
setLanguage(savedLanguage==='zh'||savedLanguage==='en'?savedLanguage:systemChinese?'zh':'en');
switchButton.addEventListener('click',()=>setLanguage(document.documentElement.lang==='en'?'zh':'en',true));
